def cmd_move(direction):
    def run(flags, args, catalog, movements, directory, raw, **_):
        date_text, sku_text, qty_text = args[0], args[1], args[2]
        note = args[3].strip(" \t") if len(args) == 4 else ""
        sku = normalise_sku(sku_text)
        if sku is None or sku not in catalog:
            raise Failure(1, "stockroom: unknown SKU %r" % sku_text)
