            raise Failure(1, "stockroom: bad quantity %r (want a whole number of one or more, no sign)" % qty_text)
        if "\n" in note or "\r" in note:
            raise Failure(1, "stockroom: a note may not contain a line break")
        quantity = to_int(qty_text) * direction
        move = Movement(parse_date(date_text), sku, quantity, note)
        message = breaks_rule(movements, move)
        if message:
            raise Failure(1, "stockroom: %s: %s" % (MOVEMENTS, message))
        line = "%s %s %s%s" % (date_text, sku, signed(quantity), " " + note if note else "")
        try:
            line.encode("utf-8")
        except UnicodeEncodeError:
            raise Failure(1, "stockroom: the note is not valid text")
        append_lines(directory, raw[MOVEMENTS], [line])
        return line + "\n"

    return run


def cmd_quote(flags, args, catalog, orders, **_):
    order = find_order(orders, args[0])
    quote = price_order(order, catalog)
    if flags.get("--json"):
        return quote_json(order, quote)
    return quote_text("%s %s %s" % (order.id, order.date.isoformat(), order.customer), quote)


def cmd_fulfil(flags, args, catalog, movements, orders, directory, raw, **_):
    order = find_order(orders, args[0])
    date = parse_date(args[1])
