class Base(unittest.TestCase):
    def setUp(self):
        self.dir = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.dir)
        self.put("catalog.txt", CATALOG)
        self.put("movements.txt", MOVEMENTS)
        self.put("orders.txt", ORDERS)

    def put(self, name, data):
        with open(os.path.join(self.dir, name), "wb") as f:
            f.write(data)

    def get(self, name):
        with open(os.path.join(self.dir, name), "rb") as f:
            return f.read()

    def run_cli(self, *args):
        return run(["--dir", self.dir] + list(args))

    def ok(self, *args):
        code, out, err = self.run_cli(*args)
        self.assertEqual((code, err), (0, ""), (args, err))
        return out

    def refused(self, code_expected, *args, mentions=()):
        before = {n: self.get(n) for n in os.listdir(self.dir)}
        code, out, err = self.run_cli(*args)
        self.assertEqual(code, code_expected, (args, out, err))
        self.assertEqual(out, "", args)
        self.assertTrue(err.strip(), args)
        for m in mentions:
            self.assertIn(m, err)
        self.assertEqual(before, {n: self.get(n) for n in os.listdir(self.dir)}, args)
        return err


class Mistakes(Base):
    def test_catalog_mistake_names_file_and_line(self):
        self.put("catalog.txt", b"# c\n\nbad line\n")
        err = self.refused(1, "stock", mentions=["catalog.txt", "line 3"])
        self.assertTrue(err.startswith("stockroom: catalog.txt: line 3:"), err)

    def test_movement_mistake(self):
        self.put("movements.txt", b"2024-03-01 AB-100 +1\n2024-03-02 AB-100 -2\n")
        self.refused(1, "stock", mentions=["movements.txt", "line 2"])

    def test_orders_mistake(self):
        self.put("orders.txt", b"SO-1 2024-01-01 a AB-100*0\n")
        self.refused(1, "quote", "SO-1", mentions=["orders.txt", "line 1"])

    def test_each_command_reads_only_its_files(self):
        self.put("orders.txt", b"junk\n")
        for args in [("stock",), ("low",), ("history", "AB-100"), ("receive", "2024-03-06", "AB-100", "1")]:
            self.assertEqual(self.run_cli(*args)[0], 0, args)
        self.put("orders.txt", ORDERS)
        self.put("movements.txt", b"junk\n")
        self.assertEqual(self.run_cli("quote", "SO-1001")[0], 0)
        for args in [("fulfil", "SO-1001", "2024-03-10"), ("invoice", "SO-1001"), ("report",), ("stock",)]:
            self.refused(1, *args, mentions=["movements.txt"])

    def test_missing_files(self):
        os.remove(os.path.join(self.dir, "movements.txt"))
        os.remove(os.path.join(self.dir, "orders.txt"))
        self.assertEqual(self.ok("stock"), "AB-100 0 out Garden gnome\nCD-205 0 out Seed packet, mix\nEF-310 0 out Gift voucher\n")
        self.assertEqual(self.ok("report"), "")
        self.assertEqual(self.ok("report", "--format", "json"), "[]\n")
        self.refused(1, "quote", "SO-1001")
        os.remove(os.path.join(self.dir, "catalog.txt"))
        for args in [("stock",), ("quote", "SO-1"), ("report",)]:
            self.refused(2, *args, mentions=["catalog.txt"])

    def test_unreadable(self):
        self.refused(2, "stock", "--dir", os.path.join(self.dir, "nope"))
        code, out, err = run(["stock", "--dir", os.path.join(self.dir, "catalog.txt")])
        self.assertEqual((code, out), (2, ""))
        self.put("movements.txt", b"2024-03-01 AB-100 +1 \xff\xfe\n")

